#!/usr/bin/env bash
# Adds the App Store purchase-verification settings to the linked Vercel
# project (production). Usage: scripts/set-apple-store-env.sh ~/Downloads/SubscriptionKey_57HFLJ5ZQG.p8
set -euo pipefail
P8="${1:?Pasa la ruta del archivo .p8 descargado de App Store Connect}"
[ -f "$P8" ] || { echo "No existe $P8"; exit 1; }

# Apple Root CA - G3 and Apple Root CA (public; SHA-256 63:34:3A:BF… and B0:B1:73:0E…)
ROOTS=","

add() { printf '%s' "$2" | vercel env add "$1" production --force >/dev/null && echo "✓ $1"; }
add APPLE_BUNDLE_ID com.guillermohaya.triwavex
add APPLE_APP_ID 6813038514
add APPLE_NOTIFICATION_ENV production
add APPLE_SERVER_API_ISSUER_ID 8528afb4-f6b7-41c4-a8a5-9e0f1378c17d
add APPLE_SERVER_API_KEY_ID 57HFLJ5ZQG
add APPLE_ROOT_CERTS_BASE64 "$ROOTS"
add APPLE_SERVER_API_PRIVATE_KEY_BASE64 "$(base64 -i "$P8" | tr -d '\n')"
echo "Listo. Redespliega con: vercel deploy --prod --yes"
